// These tests deliberately do not use basicApprovePlanMirrors: it replaces the
// invocation policy inside CommitSnapshot after seeing the generated bytes.
// That is useful sub-dispatch coverage, but cannot prove an immutable autonomous
// caller policy authorizes a complete, dynamically generated plan lifecycle.
func planAuthorityDefinition(t *testing.T) agent.PlanSnapshot {
	t.Helper()
	var definition struct {
		Goal         string               `json:"goal"`
		Context      string               `json:"context"`
		WhatNotToDo  string               `json:"what_not_to_do"`
		Verification string               `json:"verification"`
		Steps        []agent.PlanStepInfo `json:"steps"`
	}
	raw, err := json.Marshal(servicesParityPlanArgs())
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw, &definition); err != nil {
		t.Fatal(err)
	}
	preview := agent.NewPlanRuntime(nil, agent.PlanRuntimeOptions{})
	if err := preview.Announce(definition.Goal, agent.PlanDocumentInfo{Context: definition.Context, WhatNotToDo: definition.WhatNotToDo, Verification: definition.Verification}, definition.Steps); err != nil {
		t.Fatal(err)
	}
	return preview.Snapshot()
}

func planAuthorityAction(t *testing.T, r *servicesParityRuntime, name string, args map[string]any) execution.ActionDescriptor {
	t.Helper()
	raw, err := json.Marshal(args)
	if err != nil {
		t.Fatal(err)
	}
	action, err := (BotCatalogueClassifier{}).DescribeAction(r.f.ctx, name, raw)
	if err != nil {
		t.Fatal(err)
	}
	return action
}

// All grants are fixed before constructing the attempt that executes the plan.
// Neither the commit callback nor the policy/classifier/ordinary tools change.
func planAuthorityReconstruct(t *testing.T, r *servicesParityRuntime, actions ...execution.ActionDescriptor) {
	t.Helper()
	r.cleanup()
	spec := execution.RunPolicySpec{
		Identity: r.f.req.Policy.Identity(), Level: execution.AutonomySupervised,
		AllowedTools: []string{"announce_plan", "update_plan", "announce_completion", "write_file", "shell_command"},
	}
	for _, action := range actions {
		digest, err := action.Digest()
		if err != nil {
			t.Fatal(err)
		}
		spec.Grants = append(spec.Grants, execution.ScopedGrant{ID: uuid.New(), Identity: spec.Identity, ActionDigest: digest, ExpiresAt: time.Now().Add(time.Hour)})
	}
	var err error
	r.f.req.Policy, err = execution.NewRunPolicy(spec)
	if err != nil {
		t.Fatal(err)
	}
	runtime, err := r.f.construct(t)
	if err != nil {
		t.Fatal(err)
	}
	r.chat, r.cleanup = runtime.Agent, runtime.Cleanup
	t.Cleanup(r.cleanup)
}

func planAuthorityAssertFresh(t *testing.T, r *servicesParityRuntime, action execution.ActionDescriptor) {
	t.Helper()
	ctx := execution.WithBotRunIdentity(r.f.ctx, r.f.req.Policy.Identity())
	ctx = execution.WithRunPolicy(ctx, r.f.req.Policy)
	decision := execution.EvaluateRunPolicy(ctx, action, time.Now())
	if decision.Kind != execution.PolicyConsumeGrant || r.guard.consumed[decision.GrantID] {
		t.Fatalf("unrelated exact grant unavailable: %+v consumed=%v", decision, r.guard.consumed)
	}
}

// This records a real capability gap, NOT successful autonomous plan parity.
// Even a trusted preview of the exact same definition has a different generated
// identity from Announce. The production mirror also contains a wall-clock
// timestamp. There is no stable prepared-write approval/retry boundary here.
func TestChatRuntimeAutonomousPlanExactMirrorPregrantGap(t *testing.T) {
	for _, scope := range []chatruntime.ResourceScope{chatruntime.ResourceScopePersonal, chatruntime.ResourceScopeTeam} {
		t.Run(string(scope), func(t *testing.T) {
			r := newServicesParityRuntime(t, scope, "autonomous-bot")
			preview := planAuthorityDefinition(t)
			writeArgs := map[string]any{"path": filepath.Join(r.node.root, "PLAN.md"), "content": agent.NewPlanState(preview.Goal, preview.Document, preview.Steps).RenderMarkdown()}
			write := planAuthorityAction(t, r, "write_file", writeArgs)
			shellArgs := map[string]any{"command": "printf services-parity-ok", "working_dir": r.node.root}
			shell := planAuthorityAction(t, r, "shell_command", shellArgs)
			planAuthorityReconstruct(t, r, write, shell)
			policy := r.f.req.Policy
			before := *policy
			r.chat.AutoApprove = true // plan consent must not confer write authority
			planAuthorityAssertFresh(t, r, write)
			planAuthorityAssertFresh(t, r, shell)
			for attempt := 0; attempt < 2; attempt++ {
				out, err := r.invoke(t, r.f.ctx, "announce_plan", servicesParityPlanArgs())
				if err != nil || out["status"] != agent.PlanRuntimePersistFailed {
					t.Fatalf("preview grant unexpectedly authorized generated mirror: out=%v err=%v", out, err)
				}
				if len(r.node.calls) != 0 || len(r.guard.consumed) != 0 {
					t.Fatalf("failed announcement dispatched or consumed grants: calls=%v consumed=%v", r.node.calls, r.guard.consumed)
				}
			}
			p := r.chat.ToolIndex.GetToolEntry("announce_plan").Tool.(*chatRuntimeTool).binding.plan
			if snapshot := p.runtime.Snapshot(); snapshot.PlanID != "" || len(snapshot.Steps) != 0 {
				t.Fatalf("failed mirror committed plan state: %+v", snapshot)
			}
			if _, err := os.Stat(filepath.Join(r.node.root, "PLAN.md")); !os.IsNotExist(err) {
				t.Fatalf("failed announcement created mirror: %v", err)
			}
			if r.f.req.Policy != policy || !reflect.DeepEqual(before, *policy) {
				t.Fatal("announcement changed the immutable caller policy")
			}
			planAuthorityAssertFresh(t, r, write)
			planAuthorityAssertFresh(t, r, shell)
			// The original exact write is usable by the actual shared dispatcher;
			// its failure above was content mismatch, not a disabled write tool.
			if out, err := r.invoke(t, r.f.ctx, "write_file", writeArgs); err != nil || out["error"] != nil {
				t.Fatalf("exact pregranted write failed: out=%v err=%v", out, err)
			}
			raw, err := os.ReadFile(filepath.Join(r.node.root, "PLAN.md"))
			if err != nil || string(raw) != writeArgs["content"] {
				t.Fatalf("pregranted mirror bytes differ: %v", err)
			}
			if len(r.guard.consumed) != 1 || !reflect.DeepEqual(r.node.calls, []string{"write_file"}) {
				t.Fatalf("wrong exact-write accounting: calls=%v consumed=%v", r.node.calls, r.guard.consumed)
			}
			planAuthorityAssertFresh(t, r, shell)
			if _, err := r.invoke(t, r.f.ctx, "write_file", writeArgs); err == nil || len(r.node.calls) != 1 {
				t.Fatal("single-use mirror grant replayed")
			}
		})
	}
}

// TestChatRuntimeAutonomousPlanExactVerifierGrant proves positive verifier
// sub-dispatch independently of mirror persistence. Completion remains blocked.
func TestChatRuntimeAutonomousPlanExactVerifierGrant(t *testing.T) {
	for _, scope := range []chatruntime.ResourceScope{chatruntime.ResourceScopePersonal, chatruntime.ResourceScopeTeam} {
		t.Run(string(scope), func(t *testing.T) {
			r := newServicesParityRuntime(t, scope, "autonomous-bot")
			verifier := planAuthorityAction(t, r, "shell_command", map[string]any{"command": "printf services-parity-ok", "working_dir": r.node.root, "timeout": 600, "background": false})
			planAuthorityReconstruct(t, r, verifier)
			policy := r.f.req.Policy
			before := *policy
			planAuthorityAssertFresh(t, r, verifier)
			snapshot := planAuthorityDefinition(t)
			snapshot.Document.Lifecycle = agent.PlanLifecycleApproved
			snapshot.Steps[0].Status = "running"
			sess, err := r.f.sessions.Get(r.f.ctx, &session.GetRequest{AppName: "astonish", UserID: r.f.req.Principal.Subject, SessionID: r.node.session})
			if err != nil {
				t.Fatal(err)
			}
			if err := r.f.sessions.AppendEvent(r.f.ctx, sess.Session, &session.Event{ID: uuid.NewString(), Author: "system", Timestamp: time.Now(), Actions: session.EventActions{StateDelta: map[string]any{agent.PlanSnapshotStateKey: snapshot}}}); err != nil {
				t.Fatal(err)
			}
			out, err := r.invoke(t, r.f.ctx, "update_plan", map[string]any{"step": "verify", "status": "complete"})
			if err != nil || out["status"] != agent.PlanRuntimePersistFailed {
				t.Fatalf("missing evidence mirror grant did not fail closed: %v %v", out, err)
			}
			if !reflect.DeepEqual(r.node.calls, []string{"shell_command"}) || len(r.guard.consumed) != 1 || len(r.node.outputs) != 1 || r.node.outputs[0]["stdout"] != "services-parity-ok" || r.node.outputs[0]["exit_code"] != float64(0) {
				t.Fatalf("independent verifier grant did not execute: calls=%v outputs=%v consumed=%v", r.node.calls, r.node.outputs, r.guard.consumed)
			}
			p := r.chat.ToolIndex.GetToolEntry("update_plan").Tool.(*chatRuntimeTool).binding.plan
			if !reflect.DeepEqual(p.runtime.Snapshot(), snapshot) {
				t.Fatal("unpersisted evidence changed authoritative state")
			}
			if r.f.req.Policy != policy || !reflect.DeepEqual(before, *policy) {
				t.Fatal("verifier changed the immutable caller policy")
			}
			// Retry cannot reuse a consumed verifier grant after mirror failure.
			if out, err := r.invoke(t, r.f.ctx, "update_plan", map[string]any{"step": "verify", "status": "complete"}); err != nil || out["status"] != agent.PlanRuntimePersistFailed || len(r.node.calls) != 1 || len(r.guard.consumed) != 1 {
				t.Fatalf("verifier grant replayed: out=%v err=%v calls=%v", out, err, r.node.calls)
			}
		})
	}
}

// A trusted stored approved plan isolates verifier authorization from the known
// announcement/mirror gap. This is restore + denial coverage, not a substitute
// for proving announce -> approve -> verify -> Results with immutable grants.
func TestChatRuntimeAutonomousPlanVerifierAuthority(t *testing.T) {
	for _, scope := range []chatruntime.ResourceScope{chatruntime.ResourceScopePersonal, chatruntime.ResourceScopeTeam} {
		t.Run(string(scope), func(t *testing.T) {
			r := newServicesParityRuntime(t, scope, "autonomous-bot")
			policy := r.f.req.Policy
			before := *policy
			shellArgs := map[string]any{"command": "printf services-parity-ok", "working_dir": r.node.root}
			shell := planAuthorityAction(t, r, "shell_command", shellArgs)
			planAuthorityAssertFresh(t, r, shell)
			snapshot := planAuthorityDefinition(t)
			snapshot.Document.Lifecycle = agent.PlanLifecycleApproved
			snapshot.Steps[0].Status = "running"
			sess, err := r.f.sessions.Get(r.f.ctx, &session.GetRequest{AppName: "astonish", UserID: r.f.req.Principal.Subject, SessionID: r.node.session})
			if err != nil {
				t.Fatal(err)
			}
			if err := r.f.sessions.AppendEvent(r.f.ctx, sess.Session, &session.Event{ID: uuid.NewString(), Author: "system", Timestamp: time.Now(), Actions: session.EventActions{StateDelta: map[string]any{agent.PlanSnapshotStateKey: snapshot}}}); err != nil {
				t.Fatal(err)
			}
			// The approved ordinary shell differs from the verifier's exact args
			// (timeout=600, background=false), so it cannot authorize the verifier.
			out, err := r.invoke(t, r.f.ctx, "update_plan", map[string]any{"step": "verify", "status": "complete"})
			if err != nil || out["status"] != agent.PlanRuntimePersistFailed {
				t.Fatalf("unexpected denied verifier result: %v %v", out, err)
			}
			if len(r.node.calls) != 0 || len(r.guard.consumed) != 0 {
				t.Fatalf("verifier inherited plan or unrelated authority: calls=%v consumed=%v", r.node.calls, r.guard.consumed)
			}
			p := r.chat.ToolIndex.GetToolEntry("update_plan").Tool.(*chatRuntimeTool).binding.plan
			if current := p.runtime.Snapshot(); !reflect.DeepEqual(current, snapshot) {
				t.Fatalf("denied verifier changed restored plan: got=%+v want=%+v", current, snapshot)
			}
			if out, err := r.invoke(t, r.f.ctx, "announce_completion", map[string]any{"outcome_observed": "must not complete"}); err != nil || out["status"] == "ok" {
				t.Fatalf("unverified plan completed: %v %v", out, err)
			}
			planAuthorityAssertFresh(t, r, shell)
			if r.f.req.Policy != policy || !reflect.DeepEqual(before, *policy) {
				t.Fatal("verifier changed caller policy")
			}
			// A successful exact dispatch proves the denied verifier did not spend
			// the unrelated grant; the unchanged real shell implementation runs.
			out, err = r.invoke(t, r.f.ctx, "shell_command", shellArgs)
			if err != nil || out["stdout"] != "services-parity-ok" {
				t.Fatalf("unrelated approved shell failed: %v %v", out, err)
			}
			if len(r.guard.consumed) != 1 || !reflect.DeepEqual(r.node.calls, []string{"shell_command"}) {
				t.Fatalf("unexpected dispatch/accounting: %v %v", r.node.calls, r.guard.consumed)
			}
			if _, err := r.invoke(t, r.f.ctx, "shell_command", shellArgs); err == nil || len(r.node.calls) != 1 {
				t.Fatalf("single-use shell replay: %v calls=%v", err, r.node.calls)
			}
		})
	}
}
